import {
  Box,
  Button,
  CircularProgress,
  TextField,
  Typography,
  Link,
} from "@mui/material";
import BaseCard from "../../../components/Cards/Card";
import { useTheme } from "@mui/material/styles";
import useMediaQuery from "@mui/material/useMediaQuery";
import { toast } from "react-hot-toast";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import { useEffect, useRef, useState } from "react";
import { setOtpData } from "../../../Redux/Slices/AuthSlice";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const VerificationScreen = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const [otpInput, setOtpInput] = useState(["", "", "", ""]);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isResending, setIsResending] = useState(false);
  const [seconds, setSeconds] = useState(15);
  const inputRefs = useRef([]);
  const [otpError, setOtpError] = useState(false);

  const { otpData } = useSelector((state) => state.auth);
  const [searchParams] = useSearchParams();
  const queryEmail = searchParams.get("email");
  const email = otpData?.email || queryEmail;

  useEffect(() => {
    let timer;
    if (seconds > 0) {
      timer = setTimeout(() => setSeconds((prev) => prev - 1), 1000);
    }
    return () => clearTimeout(timer);
  }, [seconds]);

  const handleChange = (index, value) => {
    const newOtp = [...otpInput];
    newOtp[index] = value.slice(-1);
    setOtpInput(newOtp);
    if (otpError) setOtpError(false);
    if (value && index < 3) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (e, index) => {
    if (e.key === "Backspace" && !otpInput[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const handleVerify = async () => {
    const finalOtp = otpInput.join("");
    if (finalOtp.length !== 4) {
      setOtpError(true);
      toast.error("Please enter a valid 4-digit OTP");
      return;
    }
    setOtpError(false);
    setIsVerifying(true);

    try {
      const response = await fetch(`${BASE_URL}/auth/verify-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, otp: finalOtp }),
      });

      const result = await response.json();

      if (!response.ok || result.error) {
        throw new Error(result.message || "Verification failed");
      }

      toast.success(result.message || "OTP Verified!");
      dispatch(setOtpData({ email, otp: finalOtp }));

      setTimeout(() => {
        navigate(`/forget-set-password?email=${email}&otp=${finalOtp}`, {
          state: { email, code: finalOtp },
        });
      }, 1000);
    } catch (err) {
      console.error("🚨 Verify OTP error:", err);
      toast.error(err.message || "Verification failed");
    } finally {
      setIsVerifying(false);
    }
  };

  const handleResend = async () => {
    if (!email) return toast.error("Missing email address");
    setIsResending(true);
    try {
      const response = await fetch(`${BASE_URL}/auth/resend-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      });

      const result = await response.json();

      if (!response.ok || result.error) {
        throw new Error(result.message || "Failed to resend OTP");
      }

      dispatch(setOtpData({ email, otp: result.data.otp }));
      toast.success(result.message || "Code resent successfully!");
      setSeconds(15);
      setOtpInput(["", "", "", ""]);
    } catch (err) {
      toast.error(err.message || "Something went wrong");
    } finally {
      setIsResending(false);
    }
  };

  const handlePaste = (e) => {
    e.preventDefault();
    const pasteData = e.clipboardData.getData("text").trim();
    if (!/^\d{1,4}$/.test(pasteData)) return;
    const newOtp = pasteData.split("").slice(0, 4);
    setOtpInput(newOtp);
    if (otpError) setOtpError(false);
    const lastIndex = newOtp.length - 1;
    if (lastIndex >= 0) inputRefs.current[lastIndex]?.focus();
  };

  return (
    <Box sx={{ width: "100%", display: "flex", justifyContent: "center" }}>
      <BaseCard
        maxWidth={isMobile ? "100%" : 400}
        sx={{
          width: isMobile ? "100%" : 400,
          p: 4,
          backgroundColor: "rgba(0, 0, 0, 0.7)", // Semi-transparent black
          backdropFilter: "blur(16px)", // Glassmorphism effect
          border: "1px solid #4CC66E", // Premium green full border
          borderRadius: "16px",
          boxShadow: "0 8px 32px 0 rgba(0, 0, 0, 0.8)",
        }}
      >
        <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
          {/* Logo Section */}
          <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1, mb: 1 }}>
            <img src="/favicon.svg" style={{ width: 100, height: 100, objectFit: "contain" }} alt="Logo" />

          </Box>

          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h5" sx={{ color: "#FFFFFF", mb: 0.5 }}>
              Verify Account
            </Typography>
            <Typography variant="body2" sx={{ color: "text.secondary" }}>
              Enter the 4-digit code sent to your email
            </Typography>
          </Box>

          <Box sx={{ display: "flex", gap: 1.5, justifyContent: "center" }}>
            {otpInput.map((digit, index) => (
              <TextField
                key={index}
                value={digit}
                inputRef={(el) => (inputRefs.current[index] = el)}
                onChange={(e) => handleChange(index, e.target.value)}
                onKeyDown={(e) => handleKeyDown(e, index)}
                onPaste={handlePaste}
                inputProps={{
                  maxLength: 1,
                  style: {
                    textAlign: "center",
                    fontSize: "20px",
                    padding: "12px 0",
                  },
                }}
                sx={{
                  width: "50px",
                  "& .MuiOutlinedInput-root": {
                    borderRadius: "8px",
                    backgroundColor: "rgba(255, 255, 255, 0.05)",
                    "& fieldset": {
                      borderColor:
                        otpError && !digit
                          ? "error.main"
                          : digit
                            ? "primary.main"
                            : "rgba(255, 255, 255, 0.2)",
                    },
                  },
                }}
              />
            ))}
          </Box>

          <Box sx={{ display: "flex", justifyContent: "center" }}>
            <Typography variant="body2" sx={{ color: "text.secondary" }}>
              Didn't receive the code?&nbsp;
              {seconds > 0 ? (
                <Box
                  component="span"
                  sx={{ color: "primary.main", fontWeight: 600 }}
                >
                  {seconds}s
                </Box>
              ) : (
                <Box
                  component="span"
                  onClick={handleResend}
                  sx={{
                    color: "primary.main",
                    cursor: isResending ? "not-allowed" : "pointer",
                    opacity: isResending ? 0.5 : 1,
                    textDecoration: "underline",
                  }}
                >
                  Resend Code
                </Box>
              )}
            </Typography>
          </Box>

          <Button
            variant="contained"
            onClick={handleVerify}
            disabled={isVerifying}
            startIcon={
              isVerifying && <CircularProgress size={20} color="inherit" />
            }
          >
            Verify OTP
          </Button>

          <Box
            sx={{
              display: "flex",
              justifyContent: "center",
              mt: 1,
              gap: 0.5,
            }}
          >
            <Typography variant="body2" sx={{ color: "text.secondary" }}>
              Remember your password?
            </Typography>
            <Link
              component="button"
              variant="body2"
              onClick={() => navigate("/")}
              sx={{
                color: "primary.main",
                textDecoration: "none",
                fontWeight: 600,
                cursor: "pointer",
                "&:hover": { textDecoration: "underline" },
              }}
            >
              Sign In
            </Link>
          </Box>
        </Box>
      </BaseCard>
    </Box>
  );
};

export default VerificationScreen;
